fetch("menu-image-credits.json").then(r=>r.json()).then(items=>{credits.innerHTML=items.map(x=>`<article style="background:#fff;border-radius:18px;padding:22px;overflow-wrap:anywhere"><h2 style="font-size:22px">${x.item}</h2><p>${x.title}</p><p><strong>${x.creator}</strong><br>${x.license}</p><p><a href="${x.source}" target="_blank" rel="noreferrer">Source and license details ↗</a></p></article>`).join("")}).catch(()=>{credits.textContent="Credits could not be loaded."});
